                prefix = 'E+%02d' % int_pow10

        mant = sign*dnum/(10**pow10)

        if self.precision is None:  # pragma: no cover
            format_str = u"%g%s"
        elif self.precision == 0:
            format_str = u"%i%s"
        elif self.precision > 0:
            format_str = (u"%% .%if%%s" % self.precision)

        formatted = format_str % (mant, prefix)

        return formatted

