        day_nanos = delta_to_nanoseconds(timedelta(1))

        # #1165 and #24127
        if (is_day and not offset.nanos % day_nanos) or not is_day:
            return _adjust_dates_anchored(first, last, offset,
                                          closed=closed, base=base)

    else:
        first = first.normalize()
        last = last.normalize()

