        self, hyp: BatchHypothesis, x: torch.Tensor, pre_x: torch.Tensor=None, pre_x2: torch.Tensor=None,
    ) -> Tuple[Dict[str, torch.Tensor], Dict[str, Any]]:



        scores = dict()
