def constant_time_compare(val1, val2):



    if not (isinstance(val1, bytes) and isinstance(val2, bytes)):
        raise TypeError("constant_time_compare only supports bytes")
    if len(val1) != len(val2):
        return False
    result = 0
    if six.PY3:
        for x, y in zip(val1, val2):
            result |= x ^ y
    else:
        for x, y in zip(val1, val2):
            result |= ord(x) ^ ord(y)
    return result == 0

