    for kill_idx in range(1, int(duration / kill_interval)):
        while True:
            try:
                # kill
                if kill_idx % kill_head_every_n == 0:
                    kill_header()
                else:
                    kill_worker()
                break
            except Exception as e:
                from time import sleep

                print(f"Fail to kill node, retry in 5 seconds: {e}")
                sleep(5)

        time.sleep(kill_interval)

