def _choose_unit(self, size):

        denomi = 1
        if size <= 0:
            return denomi, self._units[0]
        for unit in self._units[:-1]:
            if size / (denomi * 1024.0) < 1:
                return denomi, unit
            denomi *= 1024
        return denomi, self._units[-1]

