        if W is not None:
            warnings.warn(
                (
                    "Input argument `W` was renamed to `Xt` in v1.3 and will be removed"
                    " in v1.5."
                ),
                FutureWarning,
            )
            Xt = W

        check_is_fitted(self)
        return Xt @ self.components_

